const markCompositeDeleting = `-- name: MarkCompositeDeleting :one
UPDATE documents.indexes SET state = 'DELETING', build_cursor = NULL,
    spec_hash = sha256(spec_hash || int8send(id))
WHERE project_number = $1 AND database_id = $2 AND id = $3
    AND collection_group = $4 AND kind = 'composite' AND state <> 'DELETING'
RETURNING operation_id
`

type MarkCompositeDeletingParams struct {
	ProjectNumber   int64
	DatabaseID      string
	ID              int64
	CollectionGroup string
}

// Takes an index out of every commit and of the planner; its entries are purged afterwards. Its
// spec_hash moves aside, so the same index may be created again before the purge ends.
func (q *Queries) MarkCompositeDeleting(ctx context.Context, arg MarkCompositeDeletingParams) (*string, error) {
	row := q.db.QueryRow(ctx, markCompositeDeleting,
		arg.ProjectNumber,
		arg.DatabaseID,
		arg.ID,
		arg.CollectionGroup,
	)
	var operation_id *string
	err := row.Scan(&operation_id)
	return operation_id, err
}

