const pruneOperations = `-- name: PruneOperations :execrows
DELETE FROM documents.operations o USING (
    SELECT x.id FROM documents.operations x
    WHERE x.project_number = $1 AND x.database_id = $2 AND x.done
        AND x.create_time < now() - make_interval(secs => $3::float8)
    LIMIT $4
) d
WHERE o.project_number = $1 AND o.database_id = $2 AND o.id = d.id
`

type PruneOperationsParams struct {
	ProjectNumber int64
	DatabaseID    string
	RetentionSecs float64
	Batch         int32
}

// Deletes up to @batch of a database's operations done more than @retention_secs ago.
func (q *Queries) PruneOperations(ctx context.Context, arg PruneOperationsParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneOperations,
		arg.ProjectNumber,
		arg.DatabaseID,
		arg.RetentionSecs,
		arg.Batch,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const purgeCompositeEntries = `-- name: PurgeCompositeEntries :execrows
DELETE FROM documents.index_entries t USING (
    SELECT x.key FROM documents.index_entries x
    WHERE x.project_number = $1 AND x.database_id = $2 AND x.index_id = $3
    LIMIT $4
) d
WHERE t.project_number = $1 AND t.database_id = $2 AND t.index_id = $3
    AND t.key = d.key
`

type PurgeCompositeEntriesParams struct {
	ProjectNumber int64
	DatabaseID    string
	IndexID       int64
	Batch         int32
}

// Up to @batch entries of an index being deleted.
func (q *Queries) PurgeCompositeEntries(ctx context.Context, arg PurgeCompositeEntriesParams) (int64, error) {
	result, err := q.db.Exec(ctx, purgeCompositeEntries,
		arg.ProjectNumber,
		arg.DatabaseID,
		arg.IndexID,
		arg.Batch,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const scanIndexEntries = `-- name: ScanIndexEntries :many
SELECT key, full_key FROM documents.index_entries
WHERE project_number = $1 AND database_id = $2 AND index_id = $3
    AND key >= $4 AND key < $5
ORDER BY key
LIMIT $6
`

type ScanIndexEntriesParams struct {
	ProjectNumber int64
	DatabaseID    string
	IndexID       int64
	Lo            []byte
	Hi            []byte
	RowLimit      int32
}

type ScanIndexEntriesRow struct {
	Key     []byte
	FullKey []byte
}

// An index's entries with a stored key in [@lo, @hi), in key order: the planner's scan.
func (q *Queries) ScanIndexEntries(ctx context.Context, arg ScanIndexEntriesParams) ([]ScanIndexEntriesRow, error) {
	rows, err := q.db.Query(ctx, scanIndexEntries,
		arg.ProjectNumber,
		arg.DatabaseID,
		arg.IndexID,
		arg.Lo,
		arg.Hi,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ScanIndexEntriesRow{}
	for rows.Next() {
		var i ScanIndexEntriesRow
		if err := rows.Scan(&i.Key, &i.FullKey); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

